222	func validateAndNormalizeDeploymentInstanceSetting(setting *storepb.InstanceSetting) error {
223		switch setting.Key {
224		case storepb.InstanceSettingKey_GENERAL:
225			if setting.GetGeneralSetting() == nil {
226				return errors.New("generalSetting must be populated for key GENERAL")
227			}
228			if offset := setting.GetGeneralSetting().WeekStartDayOffset; offset < -1 || offset > 6 {
229				return errors.New("generalSetting.weekStartDayOffset must be between -1 and 6")
230			}
231		case storepb.InstanceSettingKey_STORAGE:
232			storage := setting.GetStorageSetting()
233			if storage == nil {
234				return errors.New("storageSetting must be populated for key STORAGE")
235			}
236			if storage.UploadSizeLimitMb < 0 {
237				return errors.New("storageSetting.uploadSizeLimitMb must not be negative")
238			}
239			if storage.StorageType == storepb.InstanceStorageSetting_S3 {
240				if storage.S3Config == nil {
241					return errors.New("storageSetting.s3Config is required for S3")
242				}
243				for _, field := range []struct {
244					name  string
245					value string
246				}{
247					{name: "accessKeyId", value: storage.S3Config.AccessKeyId},
248					{name: "accessKeySecret", value: storage.S3Config.AccessKeySecret},
249					{name: "endpoint", value: storage.S3Config.Endpoint},
250					{name: "region", value: storage.S3Config.Region},
251					{name: "bucket", value: storage.S3Config.Bucket},
252				} {
253					if strings.TrimSpace(field.value) == "" {
254						return errors.Errorf("storageSetting.s3Config.%s is required", field.name)
255					}
256				}
257			}
258		case storepb.InstanceSettingKey_MEMO_RELATED:
259			if setting.GetMemoRelatedSetting() == nil {
260				return errors.New("memoRelatedSetting must be populated for key MEMO_RELATED")
261			}
262		case storepb.InstanceSettingKey_NOTIFICATION:
263			notification := setting.GetNotificationSetting()
264			if notification == nil {
265				return errors.New("notificationSetting must be populated for key NOTIFICATION")
266			}
267			if email := notification.Email; email != nil && email.Enabled {
268				if strings.TrimSpace(email.SmtpHost) == "" || email.SmtpPort <= 0 || strings.TrimSpace(email.FromEmail) == "" {
269					return errors.New("enabled notification email requires smtpHost, a positive smtpPort, and fromEmail")
270				}
271				if email.UseTls && email.UseSsl {
272					return errors.New("notification email cannot enable both useTls and useSsl")
273				}
274			}
275		case storepb.InstanceSettingKey_AI:
276			if setting.GetAiSetting() == nil {
277				return errors.New("aiSetting must be populated for key AI")
278			}
279			if err := normalizeDeploymentAISetting(setting.GetAiSetting()); err != nil {
280				return err
281			}
282		case storepb.InstanceSettingKey_BASIC, storepb.InstanceSettingKey_TAGS:
283			return errors.Errorf("key %s cannot be deployment configured", setting.Key)
284		default:
285			return errors.Errorf("unsupported instance setting key %s", setting.Key)
286		}
287		return nil
288	}
