5	// UserIdentity is the linkage between an external identity subject and a local user.
6	// Uniqueness is enforced on (Provider, ExternUID); one local user may have multiple
7	// identities across different providers.
8	type UserIdentity struct {
9		ID        int32
10		UserID    int32
11		Provider  string
12		ExternUID string
13		CreatedTs int64
14		UpdatedTs int64
15	}
16	
17	// FindUserIdentity is used to filter user identities in list/get queries.
18	type FindUserIdentity struct {
19		ID        *int32
20		UserID    *int32
21		Provider  *string
22		ExternUID *string
23	}
24	
25	// DeleteUserIdentity is used to delete user identity linkage rows.
26	type DeleteUserIdentity struct {
27		ID       *int32
28		UserID   *int32
29		Provider *string
30	}
31	
32	// CreateUserIdentity creates a new external-identity linkage record.
33	// Returns the driver error on unique-constraint violation; callers are responsible
34	// for reconciling concurrent first-login races on (Provider, ExternUID).
35	func (s *Store) CreateUserIdentity(ctx context.Context, create *UserIdentity) (*UserIdentity, error) {
36		return s.driver.CreateUserIdentity(ctx, create)
37	}
38	
39	// ListUserIdentities returns all linkage records matching the filter.
40	func (s *Store) ListUserIdentities(ctx context.Context, find *FindUserIdentity) ([]*UserIdentity, error) {
41		return s.driver.ListUserIdentities(ctx, find)
42	}
43	
44	// DeleteUserIdentities deletes all linkage records matching the filter.
45	func (s *Store) DeleteUserIdentities(ctx context.Context, delete *DeleteUserIdentity) error {
46		return s.driver.DeleteUserIdentities(ctx, delete)
47	}
48	
49	// GetUserIdentity returns the first linkage record matching the filter, or nil if none found.
50	func (s *Store) GetUserIdentity(ctx context.Context, find *FindUserIdentity) (*UserIdentity, error) {
51		list, err := s.ListUserIdentities(ctx, find)
52		if err != nil {
53			return nil, err
54		}
55		if len(list) == 0 {
56			return nil, nil
57		}
58		return list[0], nil
59	}
